static String classify(SQLException e) {
  String prefix = e.getSQLState().substring(0, 2);
  return switch (prefix) {
    case "23" -> "naruszenie ograniczenia";
    case "42" -> "blad skladni SQL";
    default -> "inny blad";
  };
}

