static void executeWithConditionalRetry(Connection conn, String sql, int retryableErrorCode) throws SQLException {
  try (Statement s = conn.createStatement()) { s.execute(sql); }
  catch (SQLException e) {
    if (e.getErrorCode() == retryableErrorCode) { System.out.println("Ponawiam..."); }
    else throw e;
  }
}

