static void handleSqlException(SQLException e) {
  String category = classify(e);
  switch (category) {
    case "naruszenie ograniczenia" -> System.out.println("Dane juz istnieja lub sa niepoprawne");
    case "blad skladni SQL" -> { System.out.println("Blad w kodzie SQL!"); /* log jako blad programisty */ }
    default -> throw new RuntimeException(e);
  }
}

