class DataAccessException extends Exception { DataAccessException(String m, Throwable c) { super(m, c); } }
class DuplicateEmailException extends DataAccessException { DuplicateEmailException(Throwable c) { super("Email juz istnieje", c); } }
static void insertUser(Connection conn, String email) throws DataAccessException {
  try (Statement s = conn.createStatement()) { s.executeUpdate("INSERT INTO users VALUES (1,'" + email + "','X')"); }
  catch (SQLException e) {
    if (e.getSQLState().startsWith("23")) throw new DuplicateEmailException(e);
    throw new DataAccessException("Nieznany blad", e);
  }
}

static DataAccessException translateException(SQLException e) {
  if (e.getSQLState().startsWith("23")) return new DuplicateEmailException(e);
  return new DataAccessException("Nieznany blad", e);
}
