static void executeWithRetry(Runnable action, int maxAttempts) {
  for (int i = 0; i < maxAttempts; i++) {
    try { action.run(); return; }
    catch (RuntimeException e) {
      if (e.getCause() instanceof SQLException sqlEx && classify(sqlEx).equals("naruszenie ograniczenia")) { continue; }
      throw e;
    }
  }
}

